def transform(grid):
    result = []
    for row in grid:
        if len(row) == 0:
            result.append([])
            continue

        unique_vals = set(row)
        if len(unique_vals) <= 1:
            # Uniform row - no change
            result.append(row[:])
        else:
            # Mixed row
            # Count values
            counts = {}
            for val in row:
                counts[val] = counts.get(val, 0) + 1

            # Find minority value (lowest count)
            min_count = min(counts.values())
            n = min_count

            # Change trailing n cells to 1
            if n > 0:
                new_row = row[:-n] + [1] * n
                result.append(new_row)
            else:
                result.append(row[:])
    return result

