def transform(grid):
    """
    ARC-style transformation puzzle solver for task-101f885f.

    Rules:
    - Find unique color wall (2s) - horizontal or vertical line
    - Find shape (minority color, not background)
    - Shape moves TOWARD wall

    Transformation:
    - For horizontal wall: shape moves UP, 8s line appears at new_shape_bottom + 1
    - For vertical wall: shape moves LEFT, 8s line appears at min_c - 1
    """
    height = len(grid)
    width = len(grid[0]) if height > 0 else 1

    # Find wall
    wall_row = -1
    wall_col = -1
    wall_type = None

    for r in range(height):
        if all(grid[r][c] == 2 for c in range(width)):
            wall_row = r
            wall_type = "horizontal"
            break

    if wall_type is None:
        for c in range(width):
            if all(grid[r][c] == 2 for r in range(height)):
                wall_col = c
                wall_type = "vertical"
                break

    if wall_type is None:
        return grid.copy()

    # Find background color (most frequent)
    color_counts = {}
    for r in range(height):
        for c in range(width):
            color = grid[r][c]
            color_counts[color] = color_counts.get(color, 0) + 1

    bg = max(color_counts.keys(), key=lambda x: color_counts[x])

    # Find shape color (least frequent non-2 color)
    shape_color = None
    for c in sorted(color_counts.keys()):
        if c != 2 and c != bg and c in color_counts and color_counts[c] > 0:
            shape_color = c
            break

    if shape_color is None or color_counts[shape_color] == 0:
        shape_color = min(color_counts.keys(), key=lambda x: (color_counts[x] == 0, color_counts[x]))

    # Find shape cells
    cells = [(r, c) for r in range(height) for c in range(width) if grid[r][c] == shape_color]
    if not cells:
        return grid.copy()

    # Get bounding box of shape
    min_r, max_r = min(r for r, c in cells), max(r for r, c in cells)
    min_c, max_c = min(c for r, c in cells), max(c for r, c in cells)

    # Calculate shift - distance from wall to closest edge of shape, minus 1
    if wall_type == "horizontal":
        gap = max_r - wall_row
        shift = max(gap - 1, 0)
        new_bottom_row = max_r - shift
    else:
        gap = wall_col - max_c
        shift = max(gap - 1, 0)
        new_right_col = max_c - shift

    # Create output
    out = [row[:] for row in grid]

    # Clear old shape cells to background
    for r, c in cells:
        out[r][c] = bg

    # Move to new position
