        for c in range(m):
            if grid[0][c] == val:
                queue.append((0, c))
            if grid[n-1][c] == val and n > 1:
                queue.append((n-1, c))

        # BFS through same-value neighbors
        while queue:
            r, c = queue.popleft()
            reachability[r][c] = True
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and not reachability[nr][nc] and grid[nr][nc] == val:
