"""
ARC-style transformation puzzle (task-35d6465a)
Transformation rule: Extend same-value groups along anti-diagonals and row-cols in both directions.
"""
from collections import defaultdict

def transform(grid):
    H, W, BG = len(grid), len(grid[0]), grid[0][0]
    result = [[BG for _ in range(W)] for _ in range(H)]

    # Copy input patterns first
    for r in range(H):
        for c in range(W):
            if grid[r][c] != BG:
                result[r][c] = grid[r][c]

    pattern_cells = set((r, c) for r in range(H) for c in range(W) if grid[r][c] != BG)

    # Process anti-diags (row + col constant)
    ad_groups = defaultdict(list)
    for r, c in pattern_cells:
        ad_groups[r + c].append((r, c, grid[r][c]))

    for ad, cells in ad_groups.items():
        if len(cells) < 2:
            continue

        val_counts = defaultdict(list)
        for c in cells:
            val_counts[c[2]].append(c)

        for val, group in val_counts.items():
            if len(group) < 2:
                continue

            group = sorted(group, key=lambda x: x[0])

            # Extend from top in reverse direction (up-right)
            r, c = group[0][0], group[0][1]
            while True:
                nr, nc = r - 1, c + 1
                if 0 <= nr < H and 0 <= nc < W:
                    if (nr, nc) in pattern_cells:
                        break
                    result[nr][nc] = val
                    r, c = nr, nc
                else:
                    break

            # Extend from bottom in reverse direction (down-left)
            r, c = group[-1][0], group[-1][1]
            while True:
                nr, nc = r + 1, c - 1
                if 0 <= nr < H and 0 <= nc < W:
                    if (nr, nc) in pattern_cells:
                        break
                    result[nr][nc] = val
                    r, c = nr, nc
                else:
                    break

    # Process row-cols (row - col constant)
    acr_groups = defaultdict(list)
    for r, c in pattern_cells:
        acr_groups[r - c].append((r, c, grid[r][c]))

    for acr, cells in acr_groups.items():
        if len(cells) < 2:
            continue

        val_counts = defaultdict(list)
        for c in cells:
            val_counts[c[2]].append(c)

        for val, group in val_counts.items():
            if len(group) < 2:
                continue

            group = sorted(group, key=lambda x: x[0])

            # Extend from top in reverse direction (up-left)
            r, c = group[0][0], group[0][1]
            while True:
                nr, nc = r - 1, c - 1
                if 0 <= nr < H and 0 <= nc < W:
                    if (nr, nc) in pattern_cells:
                        break
                    result[nr][nc] = val
                    r, c = nr, nc
                else:
                    break

            # Extend from bottom in reverse direction (down-right)
            r, c = group[-1][0], group[-1][1]
            while True:
                nr, nc = r + 1, c + 1
                if 0 <= nr < H and 0 <= nc < W:
                    if (nr, nc) in pattern_cells:
                        break
                    result[nr][nc] = val
                    r, c = nr, nc
                else:
                    break

    return result

