"""
task-35d6465a transform function
Pattern: Anti-diagonal spread (row + col constant)
- Values >= 5: STAY in place
- Values < 5: Spread down-left (increasing row, decreasing col) along anti-diagonal
- Spread stops at boundary or non-background value
"""

def transform(grid):
    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Create output grid with same background
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # Find all non-background cells to spread
    background = grid[0][0]
    spreading_cells = []  # (row, col, value)
    staying_cells = []    # (row, col, value)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                spreading_cells.append((r, c, grid[r][c]))

    # Spread value < 5 down-left (increasing row, decreasing col)
    # Track blocked cells to prevent overwriting
    blocked = set()  # Positions that are occupied or will be

    for sr, sc, val in spreading_cells:
        if val >= 5:
            # Staying cell - blocks and remains
            staying_cells.append((sr, sc, val))
            blocked.add((sr, sc))
        else:
            # Spreading cell - spreads down-left
            # Start from original position (it becomes the spread value too)
            for nr, nc in [(sr, sc)]:
                if (nr, nc) not in blocked:
                    output[nr][nc] = val
                    blocked.add((nr, nc))

            # Spread down-left (increasing row, decreasing col)
            for nr in range(sr + 1, rows):
                nc = sc - (nr - sr)
                if not (0 <= nc < cols):
                    break
                if (nr, nc) not in blocked:
                    if output[nr][nc] == background:
                        output[nr][nc] = val
                        blocked.add((nr, nc))
                    else:
                        break  # blocked by non-background
                else:
                    break

    return output

