                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] in list(bg_colors):
                                # Mark as absorbed
                                visited[nr][nc] = True
                                stack.append((nr, nc))

