def transform(grid):
    """
    Apply quadrant reflection transformation to grid.

    For each non-background, non-center value in UR quadrant:
    - Output appears at rows {r, r + (height - ur_height)} 
    - Output columns include {c, c + (grid_width - ur_width)} for all c at that row
    """
    hips, cols = len(grid), len(grid[0])
    background = 8

    output = [[background] * cols for _ in range(hips)]
    h_center = cols // 2
    v_center = hips // 2

    # Set center lines
    for r in range(hips):
        output[r][h_center] = 1
    for c in range(cols):
        output[v_center][c] = 1

    # UR quadrant: rows 0-6, cols 6-10 for 15x11 grid
    ur_r_end = 7  # 0-6
    ur_c_start = h_center + 1

    for r_ur in range(ur_r_end):
        # Find values at this row in UR
        row_vals = {}
        for c_ur in range(ur_c_start, cols):
            val = grid[r_ur][c_ur]
            if val != background and val != 1:
                if val not in row_vals:
                    row_vals[val] = set()
                row_vals[val].add(c_ur - ur_c_start)

        for val, offsets in row_vals.items():
            # Output rows
            output_rows = {r_ur, r_ur + 8}

            # For each offset, generate output columns
            half_off = 6  # shift offset
            for c_off in offsets:
                for r_out in output_rows:
                    if 0 <= r_out < hips:
                        c_output1 = c_off + ur_c_start
                        c_output2 = c_off + ur_c_start + half_off
                        for c_out in [c_output1, c_output2]:
                            if 0 <= c_out < cols and c_out != h_center:
                                output[r_out][c_out] = val

    return output

