    comps = find_8_neighborhood_components(grid, bg)
    largest = max(comps, key=len)

    output = [[bg]*cols for _ in range(rows)]

    for r, c in largest:
        val = grid[r][c]
        k = 0
        while True:
            nr, nc = r + 2*k, c - 6*k
            if 0 <= nr < rows and 0 <= nc < cols:
                output[nr][nc] = val
                k += 1
            else:
                break

    return output

