    Maps 30x30 input grid to 10x10 output grid using 3x3 block analysis.

    Rules:
    - Each 3x3 input block maps to one output cell
    - Uniform blocks (all one color): output that color if not 5, else 0
    - Mixed blocks with 5: output non-5 color if it touches any edge of block
    - For blocks without 5: output minority color
    """
    out_h, out_w = len(grid) // 3, len(grid[0]) // 3
    output = [[0]*out_w for _ in range(out_h)]

    for out_r in range(out_h):
        for out_c in range(out_w):
            in_r, in_c = out_r*3, out_c*3
            block = [[grid[in_r+r][in_c+c] for c in range(3)] for r in range(3)]

            colors = {}
            for r in range(3):
                for c in range(3):
                    v = block[r][c]
                    if v != 0:
                        colors[v] = colors.get(v, 0) + 1

            if not colors:
                output[out_r][out_c] = 0
            elif len(colors) == 1:
                single = list(colors.keys())[0]
                output[out_r][out_c] = 0 if single == 5 else single
            else:
                if 5 in colors:
                    non_5_colors = [v for v in colors.keys() if v != 5]
                    for color in non_5_colors:
                        if any(block[r][c] == color for r in [0,2] for c in [0,2]):
                            output[out_r][out_c] = color
                            break
                    else:
